pageStyle:
.dk-notice {
    padding: 0px 0px 0px 0px;
    margin: 10px 0 10px 0;
    background-color: #62b4c5;
    color: #fff;
    background-repeat: no-repeat;
    background-size: 100% 100%;
    border-radius: 5px;
}

.dk-notice p.dk-notice-header {
    font-size: 22px;
    font-weight: 300;
    background-color: #62b4c5;
    background-color: rgba(255,255,255,0);
    padding-bottom: 0;
    color: #fff;
}

.dk-notice p {
    margin-bottom: 0;
    padding-left: 15px;
    padding-right: 15px;
    padding-bottom: 10px;
    padding-top: 5px;
    background-color: rgba(255,255,255,.5);
    color: #333;
    overflow: hidden;
    text-overflow: ellipsis;
font-size: 16px;
}

.dk-notice a {
    color: #2275a6;
    font-weight: 200;
    font-size: 16px;
}
